const params=new URLSearchParams(location.search),form=params.get('form')==='services'?'services':'life';
const source=CSLBook[form],$=id=>document.getElementById(id),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let activity=params.has('activity')?Number(params.get('activity')):-1;if(!Number.isInteger(activity)||activity< -1||activity>=source.length)activity=-1;
let view='overview',step=0,timer=null,lastEvidence='',inMemory={},reviewPage=null;
const key='skillos.csl7.workbook.'+form+'.v1';try{inMemory=JSON.parse(localStorage.getItem(key)||'{}')}catch{}
const title=form==='life'?'Soil & Seed Lab: Waste to Growth':'First-Aid & Emergency Preparedness';
$('title').textContent=title;$('boundary').textContent='Original Class 7 workbook · No outside pictures or sample outcomes.';
function state(){return inMemory[activity]||(inMemory[activity]={fields:{},reflection:'',step:0})}
function persist(){try{localStorage.setItem(key,JSON.stringify(inMemory));return true}catch{return false}}
function stop(){clearInterval(timer);timer=null;window.speechSynthesis?.cancel()}
function feedback(t){const el=$('feedback');if(el)el.textContent=t;lastEvidence=t}
function image(src,alt='Original workbook illustration'){return '<img class="original-figure '+(/3ff557|0701c9/.test(src)?'source-icon':'')+'" src="'+src+'" alt="'+esc(alt)+'">'}
function paragraph(b){const t=b.text||'';return (b.images||[]).map(i=>image(i)).join('')+(t?'<p>'+esc(t)+'</p>':'')}
function blocks(items){return items.map(b=>b.kind==='table'?'<div class="table-scroll"><table>'+b.rows.map((r,i)=>'<tr>'+r.map(c=>'<'+(i?'td':'th')+'>'+c.images.map(x=>image(x)).join('')+esc(c.text)+'</'+(i?'td':'th')+'>').join('')+'</tr>').join('')+'</table></div>':paragraph(b)).join('')}
const field=(id,label,type='text',value='')=>'<label>'+esc(label)+'<input id="'+id+'" data-field="'+id+'" type="'+type+'" value="'+esc(state().fields[id]??value)+'" '+(type==='number'?'min="0"':'')+'></label>';
const notes=(id,label)=>'<label>'+esc(label)+'<textarea data-field="'+id+'">'+esc(state().fields[id]||'')+'</textarea></label>';
function bindFields(){document.querySelectorAll('[data-field]').forEach(e=>{if(e.type==='checkbox')e.checked=Boolean(state().fields[e.dataset.field]);e.oninput=()=>{state().fields[e.dataset.field]=e.type==='checkbox'?e.checked:e.value;persist()}})}
function checkbox(id,label){return '<label class="check"><input type="checkbox" data-field="'+id+'">'+esc(label)+'</label>'}
function current(){return source[activity]}
function openPage(n){const allowed=activity<0?(form==='life'?[12,13,14]:[58,59,60,61,65,69,70,71,76]):current().sourcePages;$('dialog-page').innerHTML=allowed.map(p=>'<option '+(p===n?'selected':'')+'>'+p+'</option>').join('');$('page-image').src='book/page-'+n+'.webp';$('page-image').alt='Original Class 7 workbook page '+n;$('page-dialog').showModal()}
$('dialog-page').onchange=()=>{$('page-image').src='book/page-'+$('dialog-page').value+'.webp';$('page-image').alt='Original Class 7 workbook page '+$('dialog-page').value};$('close-page').onclick=()=>{$('page-dialog').close();if(document.fullscreenElement)document.exitFullscreen?.()};$('fullscreen').onclick=()=>{$('page-dialog').requestFullscreen?.().catch(()=>{})};
function render(){stop();lastEvidence='';$('activities').innerHTML=['Meet the Lab',...source.map(a=>a.title.replace(/^Activity \d+ • /,''))].map((t,i)=>'<button data-activity="'+(i-1)+'" aria-current="'+(activity===i-1)+'">'+(i?i+' · ':'')+esc(t)+'</button>').join('');document.querySelectorAll('[data-activity]').forEach(b=>b.onclick=()=>{activity=Number(b.dataset.activity);step=state().step||0;view='overview';history.replaceState(null,'','?form='+form+'&activity='+activity);render()});$('activity-title').textContent=activity<0?'Meet the Lab':current().title;$('page').textContent=activity<0?'WORKBOOK TOOLKIT':('ORIGINAL WORKBOOK · PAGES '+current().sourcePages[0]+'–'+current().sourcePages.at(-1));$('mission').textContent=activity<0?'Know your materials before you begin.':(current().overview[2]?.text||'');$('reflection').value=state().reflection||'';$('save-status').textContent='';$('view-tabs').innerHTML=activity<0?'':['overview','steps','records','pages'].map(v=>'<button data-view="'+v+'" aria-current="'+(view===v)+'">'+({overview:'Project overview',steps:'Follow picture steps',records:'My records',pages:'Original pages'}[v])+'</button>').join('');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});if(activity<0)meet();else if(view==='overview')overview();else if(view==='steps')stepView();else if(view==='records')records();else pagesView();bindFields();document.querySelectorAll('[data-open-page]').forEach(b=>b.onclick=()=>openPage(+b.dataset.openPage))}
function overview(){$('workspace').innerHTML='<section class="card source-overview">'+blocks(current().overview.slice(3))+'<button id="begin">Follow the workbook’s picture steps →</button></section>';$('begin').onclick=()=>{view='steps';step=0;state().step=0;render()}}
function meet(){let list;if(form==='life')list=CSLBook.toolkit;else list=[{name:'Paper phone, pencil, two school maps and scenario card',usage:source[0].overview.find(b=>b.text?.startsWith('In teams of three'))?.text||'',image:source[1].pages[0].flatMap(b=>b.images||[])[0]},{name:'Workbook, clipboard, drawing colours and approved item pictures',usage:source[2].overview.find(b=>b.text?.startsWith('Workbook, pencil'))?.text||'',image:source[2].pages[1].flatMap(b=>b.images||[])[1]},{name:'Reusable paper counters, response cards and checked guide pages',usage:source[3].overview.find(b=>b.text?.startsWith('Workbook, pencil, four'))?.text||'',image:source[3].overview.flatMap(b=>b.images||[])[0]},{name:'Checked help guide and school-authorised plan',usage:source[4].overview.find(b=>b.text?.startsWith('Workbook, pencil and your checked'))?.text||'',image:source[4].overview.flatMap(b=>b.images||[])[0]},{name:'Guide, portfolio records and display folder',usage:source[6].overview.find(b=>b.text?.startsWith('Approved guide,'))?.text||'',image:source[6].overview.flatMap(b=>b.images||[])[0]}];$('workspace').innerHTML='<div class="meet-grid"><section class="card"><h2>'+ (form==='life'?'Meet Your Soil & Seed Lab':'What we need')+'</h2><div class="parts">'+list.map((t,i)=>'<button data-tool="'+i+'" aria-pressed="false">'+(t.image?image(t.image,t.name):'')+'<strong>'+esc(t.name)+'</strong></button>').join('')+'</div></section><section class="card selected-tool"><div id="tool-picture"></div><h2 id="tool-name">Select an item</h2><p id="tool-usage">Its workbook description will appear here.</p><p class="fine">The picture and description come from your workbook.</p><button id="listen" disabled>Listen in English</button> <button id="stop-audio" class="secondary">Stop</button><p id="audio-status" role="status"></p><button data-open-page="'+(form==='life'?12:60)+'" class="secondary">See original toolkit page</button></section></div>';let selected;document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{stop();selected=list[+b.dataset.tool];document.querySelectorAll('[data-tool]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('tool-name').textContent=selected.name;$('tool-usage').textContent=selected.usage;$('tool-picture').innerHTML=selected.image?image(selected.image,selected.name):'';$('listen').disabled=!window.speechSynthesis||!window.SpeechSynthesisUtterance});$('listen').onclick=()=>{stop();const s=new SpeechSynthesisUtterance(selected.name+'. '+selected.usage);s.lang='en-IN';s.onerror=()=>{$('audio-status').textContent='Audio is unavailable. Read the workbook description above.'};window.speechSynthesis.speak(s)};$('stop-audio').onclick=stop}
function stepView(){const a=current();step=Math.min(step,a.steps.length-1);if(step<0){$('workspace').innerHTML='<section class="card">'+blocks(a.pages[1]||a.overview)+'</section>';return}const s=a.steps[step];let figure=s.blocks.flatMap(b=>b.images||[]).find(img=>!/3ff557|0701c9/.test(img))||s.pageFigure;const body=s.blocks.filter(b=>!b.images?.length).filter(b=>!(b.text||'').startsWith('PROJECT '));$('workspace').innerHTML='<div class="step-layout"><aside class="card step-list"><h3>Workbook sequence</h3>'+a.steps.map((t,i)=>'<button data-step="'+i+'" aria-current="'+(i===step)+'">'+'<small>Page '+t.page+'</small>'+esc(t.title)+'</button>').join('')+'</aside><div><section class="card source-stage"><div class="source-bar"><span>ORIGINAL ARTWORK · PAGE '+s.page+'</span><button class="secondary" data-open-page="'+s.page+'">Enlarge original page</button></div><h2>'+esc(s.title)+'</h2>'+(figure?'<div class="picture-stage" id="picture-stage">'+image(figure,s.title)+'<div id="motion-layer"></div></div>':'')+'<div class="source-instructions">'+blocks(body)+'</div><div class="step-actions"><button id="previous" class="secondary" '+(step===0?'disabled':'')+'>← Previous step</button><span>Step '+(step+1)+' of '+a.steps.length+'</span><button id="next" '+(step===a.steps.length-1?'disabled':'')+'>Next step →</button></div></section><section class="card interaction"><span class="eyebrow">INTERACTIVE WORKBOOK DESK</span><div id="desk"></div><div id="feedback" class="feedback" role="status">Use the workbook step and record what you actually observe.</div></section></div></div>';document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=+b.dataset.step;state().step=step;persist();render()});$('previous').onclick=()=>{step--;state().step=step;persist();render()};$('next').onclick=()=>{step++;state().step=step;persist();render()};if(form==='life')[compost,drainage,seeds,pots,measure][activity]();else [call,map,kit,scenarios,drill,guide,share][activity]()}
function records(){const a=current();$('workspace').innerHTML='<section class="card"><h2>Record your own work</h2><p>The prompts and tables below are copied from this activity’s workbook pages. Source examples remain labelled MODEL ONLY. Staff confirmation remains a real-world staff task.</p>'+a.pages.map((pg,pi)=>'<details class="record-page" '+(pi===a.pages.findIndex(page=>/short .*record|short .*log|short .*plan|Help-Point Map|Help Message|Feedback and Revision Log|Choose the Evidence/.test(page[1]?.text||''))?'open':'')+'><summary>Page '+a.sourcePages[pi]+' · '+esc(pg[1]?.text||'')+'</summary>'+editable(pg.slice(2),'p'+a.sourcePages[pi])+'</details>').join('')+'</section>'}
function editable(items,prefix){return items.map((b,i)=>{if(b.kind==='table')return '<div class="table-scroll"><table>'+b.rows.map((row,ri)=>'<tr>'+row.map((c,ci)=>'<'+(ri?'td':'th')+'>'+c.images.map(x=>image(x)).join('')+(c.text.includes('___')?'<label><span>'+esc(c.text.replace(/_{3,}/g,' [record] '))+'</span><textarea aria-label="Page record row '+ri+' column '+ci+'" data-field="'+prefix+'-'+i+'-'+ri+'-'+ci+'">'+esc(state().fields[prefix+'-'+i+'-'+ri+'-'+ci]||'')+'</textarea></label>':esc(c.text))+'</'+(ri?'td':'th')+'>').join('')+'</tr>').join('')+'</table></div>';let t=b.text||'';if(t.includes('___'))return notes(prefix+'-'+i,t.replace(/_{3,}/g,' [record] '));if(t.startsWith('□'))return checkbox(prefix+'-'+i,t.slice(1));return paragraph(b)}).join('')}
function pagesView(){$('workspace').innerHTML='<section class="card"><h2>Original workbook pages</h2><p>These are the original pages rendered from your Class 7 Word workbook, with their artwork and wording unchanged. Select a page to enlarge it.</p><div class="page-thumbs">'+current().sourcePages.map(n=>'<button data-open-page="'+n+'"><img loading="lazy" src="book/page-'+n+'.webp" alt="Original workbook page '+n+'"><span>Page '+n+'</span></button>').join('')+'</div></section>'}
function desk(html){$('desk').innerHTML=html}
function compost(){if(step===0){const items=[['Dry leaves','brown'],['Plain cardboard','brown'],['Fresh uncooked plant scraps','green'],['Plastic','reject'],['Meat, dairy or oily food','reject']];desk('<h3>Sort the inputs</h3><p>Separate browns, greens and rejected items as shown in the workbook.</p>'+items.map(([n],i)=>'<label>'+n+'<select id="sort'+i+'"><option value="">Choose a group</option><option value="brown">Browns</option><option value="green">Greens</option><option value="reject">Rejected input</option></select></label>').join('')+'<button id="sort-check">Check sorting</button>');$('sort-check').onclick=()=>feedback(items.every((v,i)=>$('sort'+i).value===v[1])?'Check: no plastic, stickers or unsuitable food enters the bin.':'Reread the source step. Dry leaves and plain cardboard are browns; fresh uncooked plant scraps are greens. Put rejected items aside for the teacher’s approved disposal route.')}else if(step===1){desk('<h3>Use the same measuring cup</h3><div class="metrics"><div class="metric">Browns<b id="b-count">0 cups</b><button id="b-add">Add one loose cup</button></div><div class="metric">Greens<b id="g-count">0 cups</b><button id="g-add">Add one cup</button></div></div>'+field('cup-size','Cup size · mL','number')+'<button id="mix-check">Check starting mix</button>');let b=0,g=0;$('b-add').onclick=()=>{$('b-count').textContent=++b+' cups'};$('g-add').onclick=()=>{$('g-count').textContent=++g+' cups'};$('mix-check').onclick=()=>feedback(b===3&&g===1?'Start with 3 loosely filled cups of browns for 1 cup of greens. This is a starting mix, not a guarantee. Record the actual amounts.':'Compare your measured cups with the workbook’s starting mix: 3 loosely filled cups of browns for 1 cup of greens.')}else if(step===2){desk(checkbox('loose','Place a loose bed of browns; mix gently and cover exposed peels with dry leaves.')+checkbox('space','Leave room for air and later mixing.')+'<button id="mix">Rehearse mixing and covering</button>');$('mix').onclick=()=>{animate('mix');feedback('Check: do not press the mixture down or seal it airtight. This rehearsal does not produce finished compost.')}}else if(step===3){desk('<h3>Ask the teacher to check moisture</h3><label>Condition observed<select id="damp"><option value="">Choose after a teacher check</option><option value="dry">Dry</option><option value="damp">Already damp</option><option value="wet">Wet / compacted</option></select></label>'+field('water-added','Measured water added · mL','number')+'<button id="care">Check the workbook care action</button>');$('care').onclick=()=>feedback(({dry:'If dry, add a little measured water and mix. Aim for damp, not dripping.',damp:'If already damp, add no water.',wet:'Tell the teacher. Add dry browns and improve airflow as directed.'})[$('damp').value]||'Ask the teacher to check the mixture first.')}else if(step===4){desk(field('team-label','Team label')+field('start-date','Start date','date')+checkbox('lid','Ventilated lid closed; air holes remain open.')+notes('site','Approved sheltered location')+'<button id="label-bin">Attach practice label</button>');$('label-bin').onclick=()=>{const layer=$('motion-layer');if(layer)layer.innerHTML='<div class="bin-label">'+esc($('team-label').value||'Team')+'<br>Compost in progress<br>'+esc($('start-date').value)+'</div>';feedback('Check: air holes remain open; the site is secure and away from food areas.')}}else desk(field('weekly-check','Next weekly check date','date')+notes('roles','Team roles for the next check')+checkbox('clean','Return tools, tidy the area, remove gloves and wash hands with soap and water.'))}
function animate(kind){const stage=$('picture-stage');if(!stage)return;stage.classList.remove('rehearse-mix','rehearse-pour');void stage.offsetWidth;stage.classList.add('rehearse-'+kind)}
function drainage(){if(step===0)desk(notes('source-a','Sample A · source / colour / visible particles')+notes('source-b','Sample B · source / colour / visible particles'));else if(step===1||step===2){desk(field('soil-a','Soil A volume · mL','number','100')+field('soil-b','Soil B volume · mL','number','100')+checkbox('filters','Identical dry filters, matching funnels and secure supports.')+checkbox('similar-moisture','Teacher prepares samples to similar starting moisture.')+'<button id="setup-check">Check setup</button>');$('setup-check').onclick=()=>feedback($('soil-a').value==='100'&&$('soil-b').value==='100'?'Check: use equal volumes and the same filling method. Do not press down. Ask the teacher to check that each funnel is steady.':'The workbook uses a loose 100 mL portion of each sample with the same filling method.')}else if(step===3){desk('<p>Measure 50 mL water for each sample. The workbook pours evenly in about 10 seconds and reads each sample at five minutes from its own start.</p>'+field('water-a','Water A · mL','number','50')+field('water-b','Water B · mL','number','50')+'<button id="pour">Rehearse the 10-second pour</button> <button id="pause" class="secondary" disabled>Pause</button><div class="progress"><span id="pour-progress" style="width:0"></span></div><output id="pour-time">Ready · no drainage result predicted</output><p class="fine">The animation shows the action only. Record the collected volume from your own test.</p>');let seconds=0,phase='pour';function tick(){seconds++;if(phase==='pour'){const amount=Math.min(10,seconds);$('pour-progress').style.width=amount*10+'%';$('pour-time').textContent=amount+' / 10 seconds · pour evenly';if(seconds===10){phase='wait';seconds=10;const layer=$('motion-layer');if(layer)layer.innerHTML='';feedback('Pour rehearsal finished. Keep timing from the start. The five-minute reading point is still ahead; no collected volume is invented.')}}else $('pour-time').textContent=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0')+' since start · read at 5:00';if(seconds>=300){stop();$('pause').disabled=true;feedback('Five minutes since the rehearsal start. Enter your actual collected volume in the next step; do not copy water levels from the diagram.')}}$('pour').onclick=()=>{if(+$('water-a').value!==50||+$('water-b').value!==50){feedback('Measure 50 mL water for each sample as in the workbook.');return}stop();seconds=0;phase='pour';$('pause').disabled=false;$('pause').textContent='Pause';$('motion-layer').innerHTML='<div class="pour-action"><span>50 mL → A</span><span>50 mL → B</span></div>';animate('pour');timer=setInterval(tick,1000);feedback('Pouring rehearsal: about ten seconds. The timer runs from the start; it does not generate drainage readings.')};$('pause').onclick=()=>{if(timer){stop();$('pause').textContent='Resume'}else{timer=setInterval(tick,1000);$('pause').textContent='Pause'}}}else if(step===4){desk(field('collected-a','A collected at 5 minutes · mL','number')+field('collected-b','B collected at 5 minutes · mL','number')+notes('test-issues','Spill, blocked filter or timing change')+'<button id="compare">Compare my readings</button>');$('compare').onclick=()=>{if($('collected-a').value===''||$('collected-b').value===''){feedback('Enter your measured readings, including zero if no water collected. Do not guess a result.');return}const a=+$('collected-a').value,b=+$('collected-b').value;if(a>50||b>50||a<0||b<0){feedback('Check your recorded units and volume: the workbook adds 50 mL to each sample.');return}feedback(a===b?'The collected volumes are equal. Less collected water may mean slower drainage or more water still held. This test does not measure fertility.':('Sample '+(a>b?'A':'B')+' collected '+Math.abs(a-b)+' mL more water. Less collected water may mean slower drainage or more water still held; this test cannot separate those effects or measure fertility.'))}}else desk(notes('repeat','Optional repeat: fresh 100 mL portions and fresh matching filters')+checkbox('tidy','Return soil as directed, rinse tools, wipe spills and wash hands.'))}
function seeds(){if(step===0)desk(field('seed-type','Seed type / batch or source')+field('seed-start','Start date','date')+field('seed-end','Agreed final observation date','date')+'<p>Count 10 intact untreated seeds. Keep the original total at 10; do not replace a seed after starting.</p>');else if(step===1)desk('<label>Paper condition<select id="paper"><option>Choose the observed condition</option><option>Evenly damp</option><option>Puddle / submerged</option></select></label><button id="paper-check">Check setup</button>');else if(step===2||step===3||step===4){desk('<h3>Seed-position map · two rows of five</h3><p>Click only positions where you observed a visible first root. A swollen seed without a visible root is not counted yet. These are your marks, not generated growth.</p><div class="seed-map">'+Array.from({length:10},(_,i)=>'<button data-seed="'+(i+1)+'" aria-pressed="'+Boolean(state().fields['seed-'+(i+1)])+'">'+(i+1)+'</button>').join('')+'</div><p id="seed-total"></p>'+field('seed-date','Observation date','date')+field('previous-total','Yesterday’s total','number')+notes('seed-care','Care action / missing or removed seeds')+'<button id="seed-record">Record my count</button> <button id="book-seed-example" class="secondary">Show workbook arithmetic example</button>');const update=()=>{const marked=Array.from({length:10},(_,i)=>i+1).filter(i=>state().fields['seed-'+i]);$('seed-total').textContent=CSLModel.seedCount(marked)+' / 10 positions marked with visible roots'};document.querySelectorAll('[data-seed]').forEach(b=>b.onclick=()=>{const id='seed-'+b.dataset.seed;state().fields[id]=!state().fields[id];b.setAttribute('aria-pressed',String(state().fields[id]));persist();update()});update();$('seed-record').onclick=()=>{const total=Array.from({length:10},(_,i)=>state().fields['seed-'+(i+1)]).filter(Boolean).length,previous=+$('previous-total').value;if($('previous-total').value===''||previous>total||previous<0){feedback('Check yesterday’s total and your visible-root marks. Count each original seed once and record removed or missing seeds.');return}feedback('Your record: yesterday '+previous+'; new today '+(total-previous)+'; total so far '+total+'. Keep the dated observation and care record.')};$('book-seed-example').onclick=()=>feedback('MODEL ONLY · Yesterday 3; new today 2; total so far 5. Complete the table with your own daily counts.')}else desk(notes('seed-location','Teacher-approved location / cover')+notes('seed-care-plan','Agreed daily care routine and checks between lessons'));if($('paper-check'))$('paper-check').onclick=()=>feedback($('paper').value==='Evenly damp'?'Prepare evenly damp paper. Check: seeds need air too; do not submerge them in water.':'Add clean water a little at a time until evenly damp. Ask the teacher to remove any puddle.')}
function pots(){if(step===0){desk('<h3>Measure and mix</h3>'+field('base-a','A · cups base medium','number','4')+field('base-b','B · cups same base medium','number','3')+field('compost-b','B · cups mature compost','number','1')+'<button id="mix-pots">Check the two mixtures</button>');$('mix-pots').onclick=()=>feedback($('base-a').value==='4'&&$('base-b').value==='3'&&$('compost-b').value==='1'?'A: 4 cups base medium. B: 3 cups base medium + 1 cup mature compost. This 25% example needs teacher approval for your seed and materials.':'Compare with the original diagram: A uses 4 cups base; B uses 3 cups base + 1 cup mature compost. Do not use unfinished compost from Activity 1.')}else if(step===1||step===2){desk('<h3>Six pot labels</h3><div class="pot-labels">'+['A1','A2','A3','B1','B2','B3'].map(id=>'<button data-pot="'+id+'">'+id+'</button>').join('')+'</div><p id="pot-detail">Select a labelled pot.</p>'+field('fill-volume','Common final fill volume','text')+field('depth','Teacher-approved packet sowing depth')+field('sowing','Common sowing date','date'));document.querySelectorAll('[data-pot]').forEach(b=>b.onclick=()=>{$('pot-detail').textContent=b.dataset.pot+': '+(b.dataset.pot[0]==='A'?'base medium':'same base medium + mature compost')+'. One fresh seed from the same batch. Keep its label fixed.'})}else if(step===3)desk(notes('moisture-rule','Teacher-demonstrated common moisture-check rule')+notes('pot-water','Actual measured water added for each pot')+checkbox('no-standing-water','Never leave pots standing in water.'));else if(step===4){desk('<h3>Balance the positions</h3><div id="pot-row" class="pot-labels"></div><button id="rotate-pots">Shift each pot one place</button>'+field('move-date','Agreed move date','date'));let order=['A1','B1','A2','B2','A3','B3'];const draw=()=>{$('pot-row').innerHTML=order.map(x=>'<span>'+x+'</span>').join('')};draw();$('rotate-pots').onclick=()=>{order.unshift(order.pop());draw();feedback('Shift each pot one place along the row, moving the end pot to the first place. Keep labels attached and record the move.')}}else desk(notes('pot-log','Medium, seed, sowing date and daily care arrangements')+notes('exceptions','Non-emergence / damage / changes to the test'))}
function measure(){if(step===0)desk(field('reading-date','Reading date','date')+field('days-sown','Days after sowing','number')+notes('pot-check','Pot labels and emergence dates checked'));else if(step===1){desk('<h3>Use the original ruler diagram</h3><p>The drawing shows a 10 cm example; it is not a result to copy.</p><button id="ruler-zero">Find ruler zero</button> <button id="shoot-tip" class="secondary">Find the shoot-tip reading</button>');$('ruler-zero').onclick=()=>feedback('Align the zero mark with the medium surface, not the bottom of the pot.');$('shoot-tip').onclick=()=>feedback('Read level with the shoot tip in cm. Do not straighten the plant by pulling it. The original illustration is an example, not your measurement.')}else if(step===2)desk(notes('leaf-observation','True leaves / seed leaves / colour / wilting / damage')+field('ruler-precision','Ruler’s smallest division · cm'));else if(step===3)desk(notes('care-record','Actual water per pot, position change and unusual event')+'<p>NE = no shoot emerged. NM = not measured today. D = plant died; record its date and retain earlier readings.</p>');else{desk('<h3>Your six-pot reading</h3><table><tr><th>Pot</th><th>Height cm / NE / NM / D</th></tr>'+['A1','A2','A3','B1','B2','B3'].map(id=>'<tr><td>'+id+'</td><td>'+field('height-'+id,id+' height / code')+'</td></tr>').join('')+'</table><button id="means">Calculate my means</button> <button id="example" class="secondary">Load workbook’s labelled example</button><div id="means-result" class="metrics"></div>'+notes('explain-means','Means, n, emergence, condition, one limitation and improvement'));$('means').onclick=()=>{const values=['A1','A2','A3','B1','B2','B3'].map(id=>$('height-'+id).value.trim().toUpperCase());if(values.some(v=>!['NE','NM','D'].includes(v)&&(v===''||!Number.isFinite(Number(v))||Number(v)<0))){feedback('Enter a measured height or a code for every pot. If n = 0, report “no mean”.');return}const results=[CSLModel.mean(values.slice(0,3)),CSLModel.mean(values.slice(3))];$('means-result').innerHTML=results.map((r,i)=>'<div class="metric">Group '+(i?'B':'A')+'<b>'+(r.value===null?'No mean':r.value.toFixed(1)+' cm')+'</b>n = '+r.n+'</div>').join('');feedback('Divide the total measured height by the number of living seedlings actually measured. Report n beside the mean. Height alone does not prove healthier growth; this small test cannot prove compost always helps.')};$('example').onclick=()=>{['A1','A2','A3','B1','B2','B3'].forEach((id,i)=>{$('height-'+id).value=[6,8,7,5,7,'NE'][i]});feedback('WORKBOOK EXAMPLE ONLY · A: 6, 8, 7 cm. B: 5, 7 cm; one NE. These are not your observations.')}}}
function call(){if(step===0)desk(notes('safe-place','Point to a safe place; how will you alert a nearby adult?')+'<button id="known-facts">Read the original scenario facts</button>');else if(step===1)desk(field('school-street','School and street')+field('entrance','Entrance and exact spot')+'<p>The workbook practice example uses River School, Station Road, main gate, beside the blue bench. Replace details only with school-approved facts.</p>');else if(step===2){desk(notes('observable','What I see / number of people / danger')+'<button id="unknown">Practise saying “I don’t know”</button>');$('unknown').onclick=()=>feedback('If asked something the card does not tell you, say “I don’t know”. Listen to the next question.')}else{desk(notes('message-first','First message / key details')+notes('listener-first','Listener’s feedback')+notes('message-revised','Revised message / key details')+notes('listener-revised','What changed and why')+'<button id="read-call">Read my practice message aloud</button><p class="fine">No number is dialled. A real partner tests your clarity; this browser does not pretend to understand your message.</p>');$('read-call').onclick=()=>{stop();const t=state().fields['message-revised']||state().fields['message-first'];if(!t){feedback('Write your practice message first.');return}if(window.speechSynthesis&&window.SpeechSynthesisUtterance){const utterance=new SpeechSynthesisUtterance(t);utterance.lang='en-IN';window.speechSynthesis.speak(utterance);feedback('Listener: mark the spot on your map. Compare maps; add a clearer landmark if needed, then swap roles.')}else feedback('Audio is unavailable; read the message to your partner and compare their map mark.')}}if($('known-facts'))$('known-facts').onclick=()=>feedback('“Near the main gate, beside the blue bench, a visitor has fallen. One person is on the ground. Broken glass is nearby. You are on the safe side of the gate.” These are all the facts you have.')}
function map(){if(step===0){desk('<h3>Use the original practice map</h3><button id="show-start">Mark the classroom start</button> <button id="source-route" class="secondary">Reveal the workbook’s example route</button>'+field('map-start','My approved starting point'));$('show-start').onclick=()=>feedback('Mark your classroom with a star on a teacher-approved outline.');$('source-route').onclick=()=>{const img=current().pages[1].flatMap(b=>b.images||[])[0];if(img)$('picture-stage').innerHTML=image(img,'Original workbook example route');feedback('Finished example from the book: classroom → corridor → office by the blue bench. Use the real landmarks and staff roles your school confirms.')}}else if(step===1)desk(field('help-role','Confirmed help point / staff role')+field('backup','Backup help point confirmed by staff')+notes('staff-question','Who is usually here? If this room is closed, where should a student ask for help?'));else if(step===2)desk(notes('route-directions','Approved turns and fixed landmark')+notes('access-note','Staff-confirmed step-free access note'));else if(step===3)desk(notes('first-map','First directions')+notes('partner-map','What the partner marked / unclear turn')+notes('revised-map','Revised directions after partner test'));else desk(field('checked-role','Staff role who will check the map')+field('check-date','Date','date')+notes('approved-map-facts','What staff actually confirmed')+'<p>Your map remains a draft until school staff check it. The simulator does not replace the school’s emergency or evacuation plan.</p>')}
function kit(){if(step===0)desk(field('care-role','Confirmed role: who provides care?')+field('restock-role','Confirmed role: who checks and restocks?'));else if(step===1||step===2){desk('<h3>Inspect the original item illustration</h3><p>The responsible adult selects safe items or pictures. Match each to its package label. Record at least four observed items; write “not shown” when necessary.</p><div class="kit-tabs">'+[1,2,3,4].map(n=>'<button data-kit-item="'+n+'">Item '+n+'</button>').join('')+'</div><div id="kit-entry"></div>');function pick(n){$('kit-entry').innerHTML=field('kit-name-'+n,'Item '+n+' · package label / name')+notes('kit-purpose-'+n,'Adult-confirmed purpose')+field('kit-user-'+n,'Who may use it?')+notes('kit-student-'+n,'What should a student do?');bindFields();feedback('Ask: “What is its purpose? Who may use it? What should a student do?” Read your explanation back to the adult. Do not open packs or practise application.')}document.querySelectorAll('[data-kit-item]').forEach(b=>b.onclick=()=>pick(b.dataset.kitItem));pick(1)}else if(step===3)desk(notes('kit-routine','School checking routine: dates, sealed packaging and missing-item reporting')+field('kit-help','Approved help point')+field('kit-backup','Backup help point'));else if(step===4)desk(notes('kit-guide','Four illustrated items and their confirmed purposes')+notes('kit-rule','One clear student safety rule'));else desk(notes('kit-partner','Partner’s difficulty using the guide')+notes('kit-revision','Specific change after feedback')+notes('kit-verification','Actual staff check / date, or pending')+'<p>A clear-looking guide is not verified until staff have checked its facts.</p>')}
function scenarios(){const station=step<3?0:step<6?1:step<9?2:3;if(station<3){const sourcePage=current().pages[station+1],facts=sourcePage.find(b=>b.text?.startsWith('CARD FACTS:'))?.text||'';const deskStep=step%3;let html='<div class="source-facts">'+esc(facts)+'</div>';if(station===0&&deskStep===0){html+='<h3>Choose and explain</h3><button data-choice="A" class="secondary">A. Pick up the pieces.</button><button data-choice="B">B. Keep clear and alert the teacher.</button><button data-choice="C" class="secondary">C. Step over the glass to inspect it.</button>'+notes('station-a-reason','My reason, using one visible fact');desk(html);document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>feedback(CSLModel.safeChoice(0,b.dataset.choice)?'Keep clear and alert the teacher. Use the visible location, hazard and people nearby in your message.':'Recheck the original picture and facts. Do not approach or handle the glass.'))}else if(station===1&&deskStep===0){const statements=['They say they feel unwell','They have food poisoning','The librarian is at the counter'];desk(html+statements.map((t,i)=>'<label>'+esc(t)+'<select id="fact'+i+'"><option value="">F or G?</option><option value="F">F · fact</option><option value="G">G · guess</option></select></label>').join('')+'<button id="facts-check">Check fact or guess</button>');$('facts-check').onclick=()=>feedback($('fact0').value==='F'&&$('fact1').value==='G'&&$('fact2').value==='F'?'These statements match the card: facts, not a diagnosis.':'Use only the card facts. You know what the classmate said and where the librarian is; you do not know the cause.')}else if(station===2&&deskStep===0){desk(html+'<button data-choice="A" class="secondary">A. Move the barrier.</button><button data-choice="B" class="secondary">B. Squeeze past the debris.</button><button data-choice="C">C. Stay clear and ask the teacher for the approved next step.</button>'+notes('station-c-reason','The fact that supports my choice'));document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>feedback(CSLModel.safeChoice(2,b.dataset.choice)?'Stay clear and ask the teacher. Do not invent a shortcut.':'The barrier and debris are visible facts. Stay clear; ask the teacher for an approved next step.'))}else if(deskStep===1)desk(html+notes('station-'+station+'-message',station===2?'Question for the teacher about the current approved route and access':'Our exact-location and factual message')+notes('station-'+station+'-listener','Listener repeated / partner feedback'));else desk(html+notes('station-'+station+'-change','Our safe response to the workbook’s teacher change card')+'<p>Use the change card printed in the source instructions above. Teacher confirms the revised response.</p>')}else if(step===9)desk('<div class="role-cards">'+['Safety spotter','Message maker','Listener','Observer'].map(t=>'<button data-role="'+t+'">'+t+'</button>').join('')+'</div><p id="role-description">Choose a role to read its workbook responsibility.</p><button id="rotate-role" class="secondary">Rotate roles for the next round</button>');else desk(notes('response-first','First attempt / observer’s specific feedback')+notes('response-replay','Changed response and replay evidence')+notes('response-adult','Actual teacher confirmation, or pending'));const descriptions={'Safety spotter':'Names a visible hazard and a safe choice.','Message maker':'Gives location and facts; asks for adult help.','Listener':'Repeats the key details and asks one clear question.','Observer':'Uses the evidence checklist and suggests one improvement.'};document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{$('role-description').textContent=descriptions[b.dataset.role]});if($('rotate-role')){let round=1;$('rotate-role').onclick=()=>{$('role-description').textContent='Round '+(++round)+': move each role one place. Everyone tries all four roles.'}}}
function drill(){if(step===0){const pg=current().pages[1];const table=pg.find(b=>b.kind==='table');desk('<h3>School-confirmed briefing</h3>'+(table?editable([table],'drill-briefing'):'')+'<p>This app rehearses the briefing. It does not authorise or start a school drill.</p>')}else if(step===1)desk(notes('approved-destination','Approved destination from the staff-provided plan')+notes('participant-role','My participant role / question for the adult'));else if(step===2)desk(checkbox('authorised-signal','Start only on the authorised signal.')+checkbox('adult-directions','Follow the adult’s directions at a calm pace.')+checkbox('route-clear','Keep the route clear; do not stop for belongings or take photographs.'));else if(step===3)desk(notes('accountability','How I will help the adult account for everyone')+'<button id="missing">Rehearse a missing-person concern</button>');else if(step===4)desk(notes('finish-instruction','Authorised all-clear / return instruction')+notes('unsafe','How to tell the supervising adult if unsafe or distressed'));else desk(notes('drill-feedback','What actually happened: preparation, desk rehearsal or authorised drill')+notes('drill-improvement','One observation and proposed change for staff review'));if($('missing'))$('missing').onclick=()=>feedback('Tell the teacher privately. Do not go looking for someone or return to the building. Stay in the place the adult assigns.')}
function guide(){if(step===0)desk(checkbox('call-card','Staff-checked help-call card gathered.')+checkbox('help-map','Staff-checked help-point map and key gathered.')+checkbox('kit-guide','Kit guide gathered.')+notes('support-evidence','Scenario and drill evidence; only work actually completed'));else if(step===1)desk(editable(current().pages[1].filter(b=>b.kind==='table'),'guide-checks'));else if(step===2){desk('<h3>The New Reader Challenge</h3>'+notes('reader-task-a','Task A: help point, backup and map key — reader’s difficulty')+notes('reader-task-b','Task B: factual paper-only message — listener’s feedback')+notes('reader-task-c','Task C: kit responsibility and student boundary — reader’s difficulty')+'<p>Use: clear independently / needed a hint / not clear. The designer observes without pointing or explaining.</p>')}else if(step===3)desk(notes('reader-voice','What was clear? Where did the reader hesitate? What would help?'));else if(step===4)desk(editable(current().pages[3].filter(b=>b.kind==='table'),'revision-log'));else desk(notes('staff-facts','Staff verification of help points, routes, roles, kit information and sharing limits — or pending')+notes('retest','Retested section and reader result')+notes('unresolved','Unresolved detail / next action')+'<p>A peer test checks clarity. School staff verify facts and approve use.</p>')}
function share(){if(step===0)desk(editable(current().pages[1].filter(b=>b.kind==='table'),'portfolio')+notes('strongest-evidence','My strongest piece of evidence and what it shows')+notes('honest-gap','A gap I will report honestly'));else if(step===1)desk(notes('speaking-part','My speaking / communication part')+notes('show-evidence','Evidence I will point to')+notes('rehearsal-feedback','Partner feedback and one change before presenting')+'<button id="rehearse">Start the workbook’s two-minute rehearsal guide</button><output id="rehearsal-time"></output>');else desk(editable(current().pages[3].filter(b=>b.kind==='table'),'handover')+notes('handover-pending','If handover has not happened: pending and agreed next action'));if($('rehearse'))$('rehearse').onclick=()=>{stop();let sec=0;$('rehearsal-time').textContent='First 20 seconds · We created this guide for…';timer=setInterval(()=>{sec++;$('rehearsal-time').textContent=sec+' seconds · '+(sec<20?'We created this guide for… The need we noticed was…':sec<60?'This checked sheet helps because… Our evidence is…':sec<100?'Feedback showed… We changed… I contributed…':'Students should… Adults take responsibility for… What would you like to ask?');if(sec>=120){stop();feedback('The time guide is flexible; clarity matters more than speed. Record your partner’s feedback and one change before presenting.')}},1000)}}
$('reflection').oninput=()=>{state().reflection=$('reflection').value;persist()};
$('save').onclick=()=>{state().reflection=$('reflection').value;try{persist();const project='skillos.project.'+(form==='life'?'soil-seed-7':'preparedness-7');const record=JSON.parse(localStorage.getItem(project)||'{}');record.simulator=record.simulator||{};record.simulator[String(activity)]={activity:activity<0?'Meet the Lab':current().title,observation:state().reflection,modelFeedback:lastEvidence,workbookFields:state().fields,basis:'Class 7 original workbook v10',kind:'workbook rehearsal / learner-entered record',savedAt:new Date().toISOString()};localStorage.setItem(project,JSON.stringify(record));$('save-status').textContent='Saved to this project’s workbook notebook in this browser.'}catch{$('save-status').textContent='Could not save. Copy your record before leaving; browser storage is unavailable.'}};
$('reset').onclick=()=>{stop();render()};window.addEventListener('pagehide',stop);step=state().step||0;render();
